result = await mcp.call_tool("tools", "ox-bridge-write", {"path": "medmath.py", "content": """"Dimensional-analysis mini-library for medication math education.

Units are built from simple named units (each with a physical dimension and a
scale to its coherent base unit: gram for mass, liter for volume):

    mcg, mg, g, kg        (mass;   1 g = 1000 mg, 1 mg = 1000 mcg, 1 kg = 1000 g)
    mL, L                 (volume; 1 L = 1000 mL)

A Unit tracks numerator/denominator lists of simple names, a combined scale,
and combined dimension exponents.  Quantities carry a float value and a Unit.
"""

import re


class UnitError(Exception):
    """Raised for incompatible unit operations or malformed unit names."""


# name -> (dimension, scale to coherent base unit)
_SIMPLE = {
    "mcg": ("M", 1e-6),
    "mg": ("M", 1e-3),
    "g": ("M", 1.0),
    "kg": ("M", 1e3),
    "mL": ("V", 1e-3),
    "L": ("V", 1.0),
}


class Unit:
    """A (possibly compound) unit, e.g. mg, mg/mL, mg/kg."""

    def __init__(self, num=(), den=()):
        # Cancel simple names appearing on both sides (mg/mL * mL -> mg).
        num, den = list(num), list(den)
        for name in list(num):
            if name in den:
                num.remove(name)
                den.remove(name)
        for name in num + den:
            if name not in _SIMPLE:
                raise UnitError(f"unknown unit: {name!r}")
        self.num = tuple(num)
        self.den = tuple(den)
        self.scale = 1.0
        dims = {}
        for sign, names in ((+1, self.num), (-1, self.den)):
            for n in names:
                dim, sc = _SIMPLE[n]
                self.scale *= sign * sc if False else (sc if sign > 0 else 1 / sc)
                dims[dim] = dims.get(dim, 0) + sign
        self.dims = tuple(sorted(dims.items()))

    @property
    def name(self):
        top = "*".join(self.num) or "1"
        return top + ("/" + "/".join(self.den) if self.den else "")

    def times(self, other, divide=False):
        b_num, b_den = other.den, other.num if divide else other.num, other.den
        return Unit(self.num + b_num, self.den + b_den)

    def __truediv__(self, other):
        return Unit(self.num + other.den, self.den + other.num)

    def __mul__(self, other):
        return Unit(self.num + other.num, self.den + other.den)

    def __eq__(self, other):
        return isinstance(other, Unit) and self.name == other.name

    def __hash__(self):
        return hash(self.name)

    def __repr__(self):
        return f"Unit({self.name!r})"


MCG, MG, G, KG, ML, L = (Unit((n,)) for n in ("mcg", "mg", "g", "kg", "mL", "L"))


class Quantity:
    """A value together with a Unit."""

    def __init__(self, value, unit):
        self.unit = unit if isinstance(unit, Unit) else parse_unit(unit)
        self.value = float(value)

    # -- arithmetic ---------------------------------------------------------
    def _compatible_add(self, other):
        return isinstance(other, Quantity) and other.unit.dims == self.unit.dims

    def _add(self, other, sign):
        if not self._compatible_add(other):
            a, b = self.unit.name, getattr(other.unit, "name", type(other).__name__)
            raise UnitError(f"cannot add/subtract {a} and {b}: incompatible dimensions")
        # Result is expressed in the finer (smaller-scale) unit.
        mine, theirs = self.unit, other.unit
        if theirs.scale < mine.scale:
            mine, theirs = theirs, mine
        total = self._base() + sign * other._base()
        return Quantity(total / mine.scale, mine)

    def __add__(self, other):
        return self._add(other, +1)

    __radd__ = __add__

    def __sub__(self, other):
        return self._add(other, -1)

    def __mul__(self, other):
        if isinstance(other, Quantity):
            return Quantity(self.value * other.value, self.unit * other.unit)
        return Quantity(self.value * other, self.unit)

    __rmul__ = __mul__

    def __truediv__(self, other):
        if isinstance(other, Quantity):
            return Quantity(self.value / other.value, self.unit / other.unit)
        return Quantity(self.value / other, self.unit)

    def __rtruediv__(self, other):  # scalar / Quantity -> inverse unit
        return Quantity(other / self.value, Unit(self.unit.den, self.unit.num))

    def __neg__(self):
        return Quantity(-self.value, self.unit)

    # -- comparisons / display ---------------------------------------------
    def _base(self):
        return self.value * self.unit.scale

    def __eq__(self, other):
        if not isinstance(other, Quantity):
            return NotImplemented
        return (
            self.unit.dims == other.unit.dims
            and abs(self._base() - other._base()) <= 1e-9 * max(abs(self._base()), abs(other._base()), 1e-300)
        )

    def __repr__(self):
        return f"Quantity({self.value!r}, {self.unit.name!r})"

    def __str__(self):
        return f"{self.value:g} {self.unit.name}"


def parse_unit(text):
    """Parse 'mg', 'mg/mL', 'mg*kg' etc.; raise UnitError on unknown names."""
    text = text.strip()
    if "/" in text:
        top, _, bottom = text.partition("/")
        return Unit(parse_unit(top).num + parse_unit(bottom).den,
                    parse_unit(bottom).num + parse_unit(top).den)
    names = text.split("*")
    if not names or any(n.strip() not in _SIMPLE for n in names):
        bad = next((n.strip() for n in names if n.strip() not in _SIMPLE), text)
        raise UnitError(f"unknown unit: {bad!r}")
    return Unit(tuple(n.strip() for n in names))


def parse(text):
    """Parse '450 mg' or '25 mg/kg' into a Quantity."""
    m = re.fullmatch(r"\s*([-+]?\d*\.?\d+(?:[eE][-+]?\d+)?)\s+(\S+)\s*", text)
    if not m:
        raise UnitError(f"cannot parse quantity: {text!r}")
    return Quantity(float(m.group(1)), parse_unit(m.group(2)))
